module sequential_processor(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] N,\n    output reg [7:0] instruction,\n    output reg valid,\n    output reg done\n);\n    \n    // State declarations\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] GENERATE = 2'd1;\n    localparam [1:0] DONE_ST = 2'd2;\n    \n    reg [1:0] state;\n    reg [7:0] counter;\n    reg [7:0] N_reg;\n    \n    // Maximum instruction counters\n    function [7:0] max_counter(input [7:0] n);\n        case (n)\n            8'd0: max_counter = 8'd1;\n            8'd1: max_counter = 8'd1;\n            8'd2: max_counter = 8'd3;\n            8'd5: max_counter = 8'd3;\n            default: max_counter = 8'd1;\n        endcase\n    endfunction\n    \n    // Instruction lookup\n    function [7:0] get_instruction(input [7:0] n, input [7:0] idx);\n        case (n)\n            8'd0: begin\n                case (idx)\n                    8'd0: get_instruction = {3'b001, 2'b10, 3'b000};  // ZE Y\n                    default: get_instruction = {3'b101, 2'b10, 3'b000}; // DI Y\n                endcase\n            end\n            8'd1: begin\n                case (idx)\n                    8'd0: get_instruction = {3'b000, 2'b10, 3'b000};  // ST Y\n                    default: get_instruction = {3'b101, 2'b10, 3'b000}; // DI Y\n                endcase\n            end\n            8'd2: begin\n                case (idx)\n                    8'd0: get_instruction = {3'b010, 2'b00, 3'b000};  // PH A\n                    8'd1: get_instruction = {3'b011, 2'b01, 3'b000};  // PL X\n                    8'd2: get_instruction = {3'b100, 2'b10, 3'b000};  // AD Y\n                    default: get_instruction = {3'b101, 2'b10, 3'b000};  // DI Y\n                endcase\n            end\n            8'd5: begin\n                case (idx)\n                    8'd0: get_instruction = {3'b010, 2'b00, 3'b000};  // PH A\n                    8'd1: get_instruction = {3'b011, 2'b01, 3'b000};  // PL X\n                    8'd2: get_instruction = {3'b100, 2'b10, 3'b000};  // AD Y\n                    default: get_instruction = {3'b101, 2'b10, 3'b000};  // DI Y\n                endcase\n            end\n            default: begin\n                case (idx)\n                    8'd0: get_instruction = {3'b001, 2'b10, 3'b000};  // ZE Y\n                    default: get_instruction = {3'b101, 2'b10, 3'b000};  // DI Y\n                endcase\n            end\n        endcase\n    endfunction\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            instruction <= 8'd0;\n            valid <= 1'b0;\n            done <= 1'b0;\n            counter <= 8'd0;\n            N_reg <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    valid <= 1'b0;\n                    done <= 1'b0;\n                    if (start) begin\n                        N_reg <= N;\n                        counter <= 8'd0;\n                        state <= GENERATE;\n                    end\n                end\n                \n                GENERATE: begin\n                    instruction <= get_instruction(N_reg, counter);\n                    valid <= 1'b1;\n                    \n                    if (counter == max_counter(N_reg)) begin\n                        done <= 1'b1;\n                        state <= DONE_ST;\n                    end else begin\n                        counter <= counter + 8'd1;\n                    end\n                end\n                \n                DONE_ST: begin\n                    valid <= 1'b0;\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n    \nendmodule